Hook.Script:
// Set up variables for "Override GetNext" hook

var root = xmldom.getDocumentElement ();
var list = system.selectNodeList ( root,  XMLInput.connector.getParser().getParam("xmlEntryTag") );

var counter = 0;

// Initialization is done in the "After Selection" hook

function deep_parse ( node )
{
	var attr = system.newAttribute ( node.getNodeName () );		
    node = node.getFirstChild ();
    while ( node != null ) {
                var node_value = null;
		if (node.getNodeType() == 1) {		// ELEMENT_NODE == 1
			if (node.getNodeName().equals(XMLInput.connector.getParser().getParam("xmlValueTag"))) {
				node_value = node.getFirstChild().getNodeValue().trim();
			}
			else {
				node_value = deep_parse ( node );
			}
		}

		if (node.getNodeType() == 3 ) {	// TEXT_NODE == 3
			node_value = node.getNodeValue();
			if (node_value.indexOf("\n") != -1 || node_value.trim().length() == 0 )
				node_value = null;	
			else
				node_value = node_value.trim();
		}
		if ( node_value != null ){
			attr.addValue ( node_value );
		}
        node = node.getNextSibling ();
	}
	return attr;
}
if ( counter < list.getLength() )
  nxt = list.item ( counter );
else
  nxt = null;

if ( nxt != null ) {
    var child = nxt.getFirstChild ();
    while ( child != null ) {
		if (child.getNodeType() == 1) {		// ELEMENT_NODE == 1
			var child_value = deep_parse ( child );
			entry.addAttributeValue ( child.getNodeName (), child_value ); 
		}
        child = child.getNextSibling ();
    }
    result.setStatus (1)  // Entry retrieved
	counter++;
} 
else {
    result.setStatus (0) // Signal end of input
}

function addAttributeToTree( attribute, fatherElement )
{
    var element = xmldom.createElement ( attribute.getName () );
    for( var i = 0; i < attribute.size(); i++ )
    {
		var obj = attribute.getValue (i);
		if ( obj.getClass().getName().equals("com.ibm.di.entry.Attribute") )	{
			addAttributeToTree(obj, element);
		} 
		else {
			if ( attribute.size() > 1 )	{
				var element_value = xmldom.createElement ( XMLOutput.connector.getParser().getParam("xmlValueTag") );
				element.appendChild ( element_value );
				element_value.appendChild ( xmldom.createTextNode ( attribute.getValue (i) ) );
			} 
			else {
				element.appendChild ( xmldom.createTextNode ( attribute.getValue(i) ) );
			}
		}
    }

    fatherElement.appendChild ( element );
}

var root = xmldom.getDocumentElement ();
var entry = xmldom.createElement ( XMLOutput.connector.getParser().getParam("xmlEntryTag") );
var names = work.getAttributeNames ();

for ( var i = 0; i < names.length; i++ ) {
	addAttributeToTree ( work.getAttribute ( names[i] ), entry );
}

root.appendChild ( entry );
